package reference

import (
	"errors"
	"io/fs"
	"os"
	"path/filepath"

	"github.com/adejoux/tfrefdoc/internal/tfschema"
)

// PagePath returns the docs page of an entity, relative to the docs
// directory, as generated by tfplugindocs.
func PagePath(p *tfschema.Provider, e tfschema.Entity) string {
	if e.Kind == tfschema.KindProvider {
		return "index.md"
	}
	return filepath.Join(e.Kind.Dir(), p.ShortName(e.Name)+".md")
}

// Result reports what happened to one page.
type Result struct {
	Path    string
	Changed bool
	// Skipped is set when the page does not exist or has no schema section.
	Skipped string
}

// UpdateDocs rewrites the schema section of every page of the provider found
// under dir. When dryRun is set, files are not written.
func UpdateDocs(dir string, p *tfschema.Provider, opts Options, dryRun bool) ([]Result, error) {
	var results []Result
	for _, e := range p.Entities() {
		rel := PagePath(p, e)
		path := filepath.Join(dir, rel)
		b, err := os.ReadFile(path)
		if errors.Is(err, fs.ErrNotExist) {
			results = append(results, Result{Path: rel, Skipped: "page not found"})
			continue
		}
		if err != nil {
			return nil, err
		}
		out, err := ReplaceSection(string(b), Render(e, opts))
		if errors.Is(err, ErrNoSchemaSection) {
			results = append(results, Result{Path: rel, Skipped: "no schema section"})
			continue
		}
		if err != nil {
			return nil, err
		}
		changed := out != string(b)
		if changed && !dryRun {
			if err := os.WriteFile(path, []byte(out), 0o644); err != nil {
				return nil, err
			}
		}
		results = append(results, Result{Path: rel, Changed: changed})
	}
	return results, nil
}
